#include <cstddef>
#include <cstdint>
static void put(uint8_t*o,size_t p,double x){union{double f;uint64_t u;}b={.f=x};for(size_t k=0;k<8;k++)o[p+k]=uint8_t(b.u>>(8*k));}
extern "C" int64_t jacobi_iteration_method(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<2||n>26)return -1;auto d=v[0],it=v[1];if(d<2||d>4||it<1||it>8||n!=2+size_t(d*d+2*d))return -1;double a[4][4]{},b[4]{},x[4]{},y[4]{};size_t rhs=2+size_t(d*d),ini=rhs+size_t(d);for(int64_t i=0;i<d;i++){double off=0;for(int64_t j=0;j<d;j++){auto z=v[2+i*d+j];if(z<0||z>4000)return -1;a[i][j]=double(z)/1000.;if(j!=i)off+=a[i][j];}if(a[i][i]<=off)return -1;b[i]=double(v[rhs+i])/1000.;x[i]=double(v[ini+i])/1000.;if(v[rhs+i]<-2000||v[rhs+i]>2000||v[ini+i]<-2000||v[ini+i]>2000)return -1;}size_t bytes=size_t(d)*8;if(!out||cap<bytes)return -2;for(int64_t k=0;k<it;k++){for(int64_t i=0;i<d;i++){double sum=0;for(int64_t j=0;j<d;j++)if(i!=j)sum+=-a[i][j]*x[j];y[i]=(sum+b[i])/a[i][i];}for(int64_t i=0;i<d;i++)x[i]=y[i];}for(int64_t i=0;i<d;i++)put(out,size_t(i)*8,x[i]);return int64_t(bytes);}
